import { test } from 'node:test';
import assert from 'node:assert/strict';
import { montarFicha, atualizarFicha } from './solution.mjs';

test('montarFicha cria o objeto com as três propriedades', () => {
  assert.deepEqual(montarFicha('Ana', 15, 'São Paulo'), { nome: 'Ana', idade: 15, cidade: 'São Paulo' });
});

test('montarFicha com outra pessoa troca os valores', () => {
  assert.deepEqual(montarFicha('Bruno', 17, 'Campinas'), { nome: 'Bruno', idade: 17, cidade: 'Campinas' });
});

test('atualizarFicha troca um campo que já existe', () => {
  const ficha = montarFicha('Ana', 15, 'São Paulo');
  atualizarFicha(ficha, 'idade', 16);
  assert.equal(ficha.idade, 16);
});

test('atualizarFicha cria um campo que não existia', () => {
  const ficha = montarFicha('Ana', 15, 'São Paulo');
  atualizarFicha(ficha, 'telefone', '(11) 9999-0000');
  assert.equal(ficha.telefone, '(11) 9999-0000');
  assert.equal(ficha.nome, 'Ana');
});

solutionCode:
export function montarFicha(nome, idade, cidade) {
  return { nome: nome, idade: idade, cidade: cidade };
}

export function atualizarFicha(ficha, campo, valor) {
  ficha[campo] = valor;
  return ficha;
}
